func.func @transpose_then_pad(%arg0: !sym.tensor<[32, 64], f32>) -> !sym.tensor<[66, 32], f32> {
  %0 = reloc.transpose %arg0 perm [1, 0] : !sym.tensor<[32, 64], f32> -> !sym.tensor<[64, 32], f32>
  %1 = reloc.pad %0 axis 0 lo 1 hi 1 value (0.000000e+00 : f32) : !sym.tensor<[64, 32], f32> -> !sym.tensor<[66, 32], f32>
  return %1 : !sym.tensor<[66, 32], f32>
}
